const raw = $input.first().json.body;
const event = raw?.event;
if (!raw?.data || event !== 'messages.upsert') {
  return [{ json: { skip: true, reason: 'not_message', event } }];
}
const msgKey = raw.data.key || {};
if (msgKey.fromMe) return [{ json: { skip: true, reason: 'fromMe' } }];
const remoteJid = msgKey.remoteJid || '';
if (remoteJid.endsWith('@g.us')) return [{ json: { skip: true, reason: 'group' } }];
const status = raw.data.status;
if (status && status !== 'PENDING') {
  return [{ json: { skip: true, reason: 'duplicate_status', status } }];
}
const TIPOS = ['conversation','extendedTextMessage','audioMessage','imageMessage','documentMessage','documentWithCaptionMessage'];
const messageType_raw = raw.data.messageType || '';
if (!TIPOS.includes(messageType_raw)) {
  return [{ json: { skip: true, reason: 'type_ignored', messageType_raw } }];
}
const msgObj = raw.data.message || {};
const celular = remoteJid.replace(/@.+/, '');
const base = { skip: false, jid: remoteJid, celular, numberToSend: remoteJid,
  pushName: raw.data.pushName || '', msgId: msgKey.id || '',
  messageType_raw, msgKey, msgObj, centro_id: 'a1b2c3d4-0000-0000-0000-000000000001' };
if (messageType_raw === 'conversation') {
  const userText = msgObj.conversation || '';
  if (!userText.trim()) return [{ json: { skip: true, reason: 'empty' } }];
  return [{ json: { ...base, tipo: 'text', userText, msgKey: undefined, msgObj: undefined } }];
}
if (messageType_raw === 'extendedTextMessage') {
  const userText = msgObj.extendedTextMessage?.text || '';
  if (!userText.trim()) return [{ json: { skip: true, reason: 'empty' } }];
  return [{ json: { ...base, tipo: 'text', userText, msgKey: undefined, msgObj: undefined } }];
}
if (messageType_raw === 'audioMessage') {
  return [{ json: { ...base, tipo: 'audio', userText: '' } }];
}
if (messageType_raw === 'imageMessage') {
  const caption = msgObj.imageMessage?.caption || '';
  return [{ json: { ...base, tipo: 'image', userText: caption ? `[Imagen] ${caption}` : '[Imagen recibida]', caption } }];
}
if (messageType_raw === 'documentMessage' || messageType_raw === 'documentWithCaptionMessage') {
  const docMsg = msgObj.documentMessage || {};
  const caption = docMsg.caption || '';
  const fileName = docMsg.fileName || 'documento';
  return [{ json: { ...base, tipo: 'document', userText: `[Documento: ${fileName}] ${caption}`.trim(), fileName } }];
}
return [{ json: { skip: true, reason: 'unhandled', messageType_raw } }];

const p = $input.first().json;
return [{ json: {
  celular: p.celular,
  numberToSend: p.numberToSend,
  pushName: p.pushName,
  jid: p.jid,
  msgId: p.msgId,
  centro_id: p.centro_id,
  tipo: 'text',
  userText: p.userText,
  imageBase64: null,
  documentBase64: null
}}];

const whisperOut = $input.first().json;
const transcripcion = whisperOut.text || '[No se pudo transcribir]';
const parsed = $('Parsear Mensaje').first().json;
return [{ json: {
  celular: parsed.celular,
  numberToSend: parsed.numberToSend,
  pushName: parsed.pushName,
  jid: parsed.jid,
  msgId: parsed.msgId,
  centro_id: parsed.centro_id,
  tipo: 'audio',
  userText: '[Audio transcripto]: ' + transcripcion,
  imageBase64: null,
  documentBase64: null
}}];

const b64 = $input.first().json.base64 || '';
const parsed = $('Parsear Mensaje').first().json;
return [{ json: {
  celular: parsed.celular,
  numberToSend: parsed.numberToSend,
  pushName: parsed.pushName,
  jid: parsed.jid,
  msgId: parsed.msgId,
  centro_id: parsed.centro_id,
  tipo: 'image',
  userText: parsed.userText,
  imageBase64: b64,
  documentBase64: null
}}];
